#!/bin/bash
# Gate for the EulerIneq Lean formalisation (Euler's theorem and the inequalities around it). Passes only if all of these hold:
#  * the sources contain no `sorry`, `admit`, `native_decide`, `axiom`, `#eval`, `run_cmd`,
#    `initialize`, `IO`, `set_option`, or syntax-extension commands (which could redefine
#    `#print axioms`);
#  * the library builds without errors;
#  * the gate itself generates the `#print axioms` report for each REQUIRED theorem;
#  * each REQUIRED theorem uses only Lean's standard axioms (propext, Classical.choice, Quot.sound).
# SCAFFOLD=1 skips the forbidden-token check and also tolerates `sorryAx`, so a partially
# finished development can be checked while it still contains `sorry`.
export PATH="$HOME/.elan/bin:$PATH"
cd "$(dirname "$0")" || exit 1
NS="EulerIneq"
LIB="EulerIneq"
REQUIRED="EulerIneq.area EulerIneq.semiperimeter EulerIneq.euler EulerIneq.four_mul_area_mul_circumradius_sub EulerIneq.euler_inequality EulerIneq.eq_zero_of_pos_mul_sq EulerIneq.sum_three_eq_zero EulerIneq.euler_inequality_eq_iff EulerIneq.euler_excenter EulerIneq.hf_identity EulerIneq.hf_L_nonneg EulerIneq.hadwiger_finsler EulerIneq.hadwiger_finsler_eq_iff EulerIneq.weitzenboeck EulerIneq.weitzenboeck_eq_iff EulerIneq.core_identity EulerIneq.fundamental_quartic EulerIneq.gerretsen EulerIneq.dist_circumcenter_centroid_sq EulerIneq.dist_circumcenter_orthocenter_sq EulerIneq.dist_incenter_centroid_sq EulerIneq.gram EulerIneq.sideLen EulerIneq.sideLen_zero EulerIneq.sideLen_one EulerIneq.sideLen_two EulerIneq.side_pos EulerIneq.height_sq_mul EulerIneq.circumradius_sq_mul EulerIneq.two_mul_area_sq EulerIneq.area_nonneg EulerIneq.height_mul_sideLen EulerIneq.area_pos EulerIneq.four_mul_circumradius_mul_area EulerIneq.excenterWeightsUnnorm_eq EulerIneq.excenterWeights_eq EulerIneq.exradius_eq EulerIneq.incenter_weights EulerIneq.inradius_eq EulerIneq.sum_signed_sideLen_pos EulerIneq.dist_affineCombination_sq EulerIneq.dist_affineCombination_circumcenter_sq EulerIneq.dist_affineCombination_affineCombination_sq EulerIneq.centroid_eq_affineCombination EulerIneq.triangle_pos EulerIneq.inradius_mul EulerIneq.pedoe_identity EulerIneq.pedoe EulerIneq.pedoe_eq_iff EulerIneq.ptolemy_inequality EulerIneq.kooi_of_quartic EulerIneq.kooi EulerIneq.kooi_le_gerretsen EulerIneq.leibniz_relation EulerIneq.leibniz_min EulerIneq.leibniz_min_eq_iff EulerIneq.amgm_three EulerIneq.isoperimetric EulerIneq.isoperimetric_eq_iff EulerIneq.gerretsen_cross_check EulerIneq.l14_euler EulerIneq.l14_euler_inequality EulerIneq.l14_euler_inequality_eq_iff EulerIneq.l14_euler_excenter EulerIneq.l14_dist_circumcenter_centroid_sq EulerIneq.l14_dist_circumcenter_orthocenter_sq EulerIneq.l14_dist_incenter_centroid_sq EulerIneq.l14_fundamental_quartic EulerIneq.l14_gerretsen EulerIneq.l14_kooi EulerIneq.l14_kooi_le_gerretsen EulerIneq.l14_weitzenboeck EulerIneq.l14_weitzenboeck_eq_iff EulerIneq.l14_hadwiger_finsler EulerIneq.l14_hadwiger_finsler_eq_iff EulerIneq.l14_isoperimetric EulerIneq.l14_isoperimetric_eq_iff EulerIneq.l14_leibniz_relation EulerIneq.l14_leibniz_min EulerIneq.l14_leibniz_min_eq_iff EulerIneq.l14_pedoe EulerIneq.l14_pedoe_eq_iff EulerIneq.l14_ptolemy_inequality EulerIneq.l14_dist_sq EulerIneq.l14_dist EulerIneq.l14_not_collinear EulerIneq.l14_ne EulerIneq.l14T EulerIneq.l14T' EulerIneq.l14T_sides EulerIneq.l14T_area EulerIneq.l14T_inradius EulerIneq.l14T_circumradius EulerIneq.l14T'_sides EulerIneq.l14T'_area EulerIneq.l14_sqrt3_lt EulerIneq.l14w_triangle EulerIneq.l14w_leibniz EulerIneq.l14w_pedoe EulerIneq.l14w_ptolemy_inequality EulerIneq.Blind.BlindSemiperimeter EulerIneq.Blind.BlindArea EulerIneq.Blind.BlindHeronGamma EulerIneq.Blind.BlindEquilateral EulerIneq.Blind.BlindInClosedTriangle EulerIneq.Blind.BlindStrictlyInside EulerIneq.Blind.BlindDistToLine EulerIneq.Blind.BlindOrientationSign EulerIneq.Blind.BlindOuterApex EulerIneq.Blind.BlindApexA EulerIneq.Blind.BlindApexB EulerIneq.Blind.BlindApexC EulerIneq.Blind.BlindNapoleonA EulerIneq.Blind.BlindNapoleonB EulerIneq.Blind.BlindNapoleonC EulerIneq.Blind.blind1_stmt EulerIneq.Blind.blind2_stmt EulerIneq.Blind.blind3_stmt EulerIneq.Blind.blind4_stmt EulerIneq.Blind.blind5_stmt EulerIneq.Blind.blind6_stmt EulerIneq.Blind.blind7_stmt EulerIneq.Blind.blind8_stmt EulerIneq.Blind.blind9_stmt EulerIneq.Blind.blind10_stmt EulerIneq.Blind.blind11_stmt EulerIneq.Blind.blind12_stmt EulerIneq.Blind.blind13_stmt EulerIneq.Blind.blind14_stmt EulerIneq.Blind.blind15_stmt EulerIneq.Blind.blind16_stmt EulerIneq.Blind.blind17_stmt EulerIneq.Blind.blind18_stmt EulerIneq.Blind.blind19_stmt EulerIneq.Blind.blind20_stmt EulerIneq.Blind.blind21_stmt EulerIneq.Blind.blind22_stmt EulerIneq.Blind.blind23_stmt EulerIneq.Blind.blind24_stmt EulerIneq.Blind.blind25_stmt EulerIneq.Blind.blind26_stmt EulerIneq.Blind.blind27_stmt EulerIneq.Blind.agree_area EulerIneq.Blind.agree_semiperimeter EulerIneq.Blind.agree_centroid EulerIneq.Blind.agree_equilateral EulerIneq.Blind.agree_equilateral' EulerIneq.Blind.rb_1 EulerIneq.Blind.br_1 EulerIneq.Blind.rb_2 EulerIneq.Blind.br_2 EulerIneq.Blind.rb_3 EulerIneq.Blind.br_3 EulerIneq.Blind.rb_4 EulerIneq.Blind.rb_5 EulerIneq.Blind.rb_6 EulerIneq.Blind.br_456 EulerIneq.Blind.br_4 EulerIneq.Blind.br_5 EulerIneq.Blind.br_6 EulerIneq.Blind.rb_7 EulerIneq.Blind.br_7 EulerIneq.Blind.rb_8 EulerIneq.Blind.br_8 EulerIneq.Blind.rb_9 EulerIneq.Blind.br_9 EulerIneq.Blind.rb_10 EulerIneq.Blind.br_10 EulerIneq.Blind.rb_11 EulerIneq.Blind.rb_12 EulerIneq.Blind.br_11_12 EulerIneq.Blind.rb_13 EulerIneq.Blind.br_13 EulerIneq.Blind.rb_14 EulerIneq.Blind.br_14 EulerIneq.Blind.rb_15 EulerIneq.Blind.br_15 EulerIneq.Blind.rb_16 EulerIneq.Blind.br_16 EulerIneq.Blind.rb_17 EulerIneq.Blind.br_17 EulerIneq.Blind.rb_18 EulerIneq.Blind.br_18 EulerIneq.Blind.rb_19 EulerIneq.Blind.br_19 EulerIneq.Blind.rb_20 EulerIneq.Blind.br_20 EulerIneq.Blind.rb_21 EulerIneq.Blind.br_21 EulerIneq.Blind.rb_22 EulerIneq.Blind.br_22 EulerIneq.Blind.rb_23 EulerIneq.Blind.br_23 EulerIneq.Blind.rb_24 EulerIneq.Blind.br_24 EulerIneq.Blind.rb_25 EulerIneq.Blind.br_25 EulerIneq.Blind.rb_26 EulerIneq.Blind.br_26 EulerIneq.Blind.rb_27 EulerIneq.Blind.br_27 EulerIneq.Classical.ClassicalSideA EulerIneq.Classical.ClassicalSideB EulerIneq.Classical.ClassicalSideC EulerIneq.Classical.ClassicalSemiperimeter EulerIneq.Classical.ClassicalAreaPts EulerIneq.Classical.ClassicalArea EulerIneq.Classical.ClassicalCentroid EulerIneq.Classical.ClassicalEquilateral EulerIneq.Classical.ClassicalSumSq EulerIneq.Classical.ClassicalInsideOrOn EulerIneq.Classical.ClassicalStrictlyInside EulerIneq.Classical.ClassicalDistToLine EulerIneq.Classical.ClassicalIsFermatPoint EulerIneq.Classical.ClassicalAnglesLt120 EulerIneq.Classical.ClassicalOutwardEquilateralApex EulerIneq.Classical.ClassicalDistSum EulerIneq.Classical.ClassicalDistSqSum EulerIneq.Classical.ClassicalInOrderOnCircleOrLine EulerIneq.Classical.cov_E1 EulerIneq.Classical.cov_E2a EulerIneq.Classical.cov_E2b EulerIneq.Classical.cov_E3 EulerIneq.Classical.cov_E4a EulerIneq.Classical.cov_E4b EulerIneq.Classical.cov_E4c EulerIneq.Classical.cov_E5 EulerIneq.Classical.cov_E6a EulerIneq.Classical.cov_E6b EulerIneq.Classical.cov_E7 EulerIneq.Classical.cov_E8a EulerIneq.Classical.cov_E8b EulerIneq.Classical.cov_E9a EulerIneq.Classical.cov_E9b EulerIneq.Classical.cov_E10a EulerIneq.Classical.cov_E10b EulerIneq.Classical.cov_E11a EulerIneq.Classical.cov_E11b EulerIneq.Classical.cov_E12a EulerIneq.Classical.cov_E12b EulerIneq.Classical.cov_P1_part EulerIneq.Classical.cov_P1_counterexample EulerIneq.Classical.cov_P1_false"
SOURCES="EulerIneq/*.lean EulerIneq.lean"
[ -e .lake/packages/mathlib ] || { echo "FAIL: Mathlib packages missing (run setup by hand)"; exit 1; }
if [ "${SCAFFOLD:-0}" != "1" ]; then
  if grep -nE "\bsorry\b|\badmit\b|native_decide|\baxiom\b|#eval|\brun_cmd\b|\binitialize\b|\bIO\b|\bdebug\.|\bmacro|\belab|\bsyntax\b|\bnotation\b|\binfix|\bprefix\b|\bpostfix\b|import Lean|open Lean|\bset_option\b" $SOURCES; then
    echo "FAIL: forbidden token"; exit 1; fi
fi
build=$(lake build $LIB 2>&1); bstatus=$?
printf '%s\n' "$build" | tail -3
[ "$bstatus" -eq 0 ] || { printf '%s\n' "$build"; echo "FAIL: build"; exit 1; }
root=$(lake env lean "$LIB.lean" 2>&1) || { printf '%s\n' "$root"; echo "FAIL: build (root file)"; exit 1; }
chk=".gatecheck_$$.lean"
trap 'rm -f "$chk"' EXIT
{ echo "import $LIB"; for t in $REQUIRED; do echo "#print axioms $t"; done; } > "$chk"
out=$(lake env lean "$chk" 2>&1); status=$?
printf '%s\n' "$out"
[ "$status" -eq 0 ] || { echo "FAIL: axiom report"; exit 1; }
echo "$out" | grep -qE "(^|:)[[:space:]]*error" && { echo "FAIL: Lean reported an error"; exit 1; }
flat=$(printf '%s\n' "$out" | awk '/^'"'"'/{if(buf!="")print buf; buf=$0; next} {buf=buf" "$0} END{if(buf!="")print buf}')
reports=$(printf '%s\n' "$flat" | grep -E "depends on axioms|does not depend on any axioms")
n=0
for t in $REQUIRED; do
  te=$(printf '%s' "$t" | sed 's/[.]/\\./g')
  c=$(printf '%s\n' "$reports" | grep -cE "^'$te' (depends on axioms|does not depend)")
  [ "$c" -eq 1 ] || { echo "FAIL: expected one axiom report for $t, found $c"; exit 1; }
  n=$((n+1))
done
[ "$(printf '%s\n' "$reports" | grep -c .)" -eq "$n" ] || { echo "FAIL: unexpected extra reports"; exit 1; }
printf '%s\n' "$reports" | grep "depends on axioms" | grep -qv '\]' && { echo "FAIL: unterminated axiom list"; exit 1; }
if [ "${SCAFFOLD:-0}" = "1" ]; then ALLOW='^(propext|Classical\.choice|Quot\.sound|sorryAx)$'; else ALLOW='^(propext|Classical\.choice|Quot\.sound)$'; fi
bad=$(printf '%s\n' "$reports" | grep "depends on axioms" | sed 's/.*depends on axioms: *\[//; s/\].*//' \
      | tr ',' '\n' | sed 's/^ *//; s/ *$//' | grep -v '^$' | sort -u | grep -vE "$ALLOW")
[ -n "$bad" ] && { echo "FAIL: nonstandard axioms: $bad"; exit 1; }
echo "PASS ($n declarations, standard axioms only)"
